      "sourceNodeId": "routeDecision1",
      "sourcePort": "true",
      "targetNodeId": "notifySlackVipEscalation1",
      "targetPort": "input"
    },
    {
      "id": "e5",
      "sourceNodeId": "notifySlackVipEscalation1",
      "sourcePort": "output",
      "targetNodeId": "replyAcknowledgment1",
      "targetPort": "input"
    },
    {
      "id": "e6",
      "sourceNodeId": "replyAcknowledgment1",
      "sourcePort": "output",
      "targetNodeId": "endHighTouch1",
      "targetPort": "input"
    },
    {
      "id": "e7",
      "sourceNodeId": "routeDecision1",
      "sourcePort": "false",
      "targetNodeId": "generateTicket1",
      "targetPort": "input"
    },
    {
      "id": "e8",
      "sourceNodeId": "generateTicket1",
      "sourcePort": "success",
      "targetNodeId": "replyWithTicketDetails1",
      "targetPort": "input"
    },
